// Physical jobs first; reasons and accounting labels remain traceable.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function serviceOrderCoverage(catalogue,filter=''){
 const c=catalogue?.serviceOrders;if(!c?.orders?.length)return '';
 const q=filter.trim().toLowerCase(),types=c.engineTypes||{},workTypes=c.workTypes||c.groups.map(title=>({title}));
 const orders=c.orders.filter(o=>!q||[o.code,o.title,o.group,o.reason,o.accounting,o.behaviour,o.gap,...(o.engineTypes||[]).map(k=>types[k]||k),...(o.manualActivities||[])].join(' ').toLowerCase().includes(q));
 if(!orders.length)return '';
 const groups=workTypes.map(w=>({...w,orders:orders.filter(o=>w.id?o.workType===w.id:o.group===w.title)})).filter(w=>w.orders.length);
 const original=o=>`<article class="service-order-card" id="service-order-${esc(o.code)}"><header><h4><code>${esc(o.code)}</code> ${esc(o.title)}</h4><span class="report-status is-${esc(o.status)}">${esc(c.statuses[o.status]||o.status)}</span></header><p>${esc(o.behaviour)}</p><dl>${o.reason?`<dt>Reason</dt><dd>${esc(o.reason)}</dd>`:''}${o.accounting?`<dt>Accounting</dt><dd>${esc(o.accounting)}</dd>`:''}${o.engineTypes.length?`<dt>Related annual work</dt><dd>${o.engineTypes.map(k=>esc(types[k]||k)).join(' · ')}</dd>`:''}${o.manualActivities.length?`<dt>Related manual purpose</dt><dd>${o.manualActivities.map(esc).join(' · ')}</dd>`:''}</dl>${o.gap?`<p class="service-order-gap"><b>Coverage note:</b> ${esc(o.gap)}</p>`:''}</article>`;
 return `<section class="glossary-family service-order-coverage" id="service-orders"><h2>Service orders: one job, different reasons</h2><p><b>${groups.length} common work ${groups.length===1?'type':'types'}</b> · ${orders.length} of ${c.orders.length} reference labels</p><p>Choose the physical job, then why it is needed. Original codes stay available for lookup; they do not create extra work counts. CAPEX/OPEX stays an accounting classification.</p><details class="service-coverage-note"><summary>Issuing work and interpreting the times</summary><p>${esc(c.manualNote)}</p><p>${esc(c.timingNote)}</p><p>${esc(c.source)}</p></details>${groups.map(w=>{
  const reasons=[...new Set(w.orders.map(o=>o.reason||o.title))];
  return `<article class="service-work-type" data-work-type="${esc(w.id||w.title)}"><header><h3>${esc(w.title)}</h3><span>${w.orders.length} reference ${w.orders.length===1?'label':'labels'}</span></header>${w.description?`<p>${esc(w.description)}</p>`:''}<div class="service-reasons" aria-label="Reasons for ${esc(w.title)}">${reasons.map(r=>`<span>${esc(r)}</span>`).join('')}</div>${w.connections?.length?`<div class="service-connections">${w.connections.map(link=>`<div class="service-connection is-${esc(link.status)}"><b>${link.status==='available'?'Connected today':'Still to connect'}</b><p><span>${esc(link.trigger)}</span><span aria-hidden="true"> → </span><strong>${esc(link.job)}</strong><span aria-hidden="true"> → </span><span>${esc(link.result)}</span></p></div>`).join('')}</div>`:''}<details class="service-order-group" ${q?'open':''}><summary><strong>Original codes and coverage</strong><span>${w.orders.length} ${w.orders.length===1?'label':'labels'}</span></summary><div class="service-order-list">${w.orders.map(original).join('')}</div></details></article>`;
 }).join('')}</section>`;
}
